const crypto = require('crypto');

function encrypt(text, key = 'vnKhqSKFG2ytO9Br', iv = '3536800982263096') {
  const buffer = Buffer.from(text, 'utf8');
  const cipher = crypto.createCipheriv('aes-128-cbc', key, iv);
  cipher.setAutoPadding(true);
  const str = Buffer.concat([cipher.update(buffer), cipher.final()]).toString('hex');
  return encodeBytes(str);
}

function encodeBytes(str) {
  let ret = '';
  let charCodeOfA = 'a'.charCodeAt(0);
  for(let i=0; i<str.length; i++) {
    ret += String.fromCharCode(charCodeOfA + parseInt(str.charAt(i), 16));
  }
  return ret;
}

function decrypt(text, key = 'vnKhqSKFG2ytO9Br', iv = '3536800982263096') {
  const str = decodeBytes(text)
  const buff = new Buffer(str, 'hex');
  const decipher = crypto.createDecipheriv('aes-128-cbc', key, iv);
  decipher.setAutoPadding(true);
  return Buffer.concat([decipher.update(buff), decipher.final()]).toString('utf8');
}

function decodeBytes(str) {
  let ret = '';
  let charCodeOfA = 'a'.charCodeAt(0);
  for(let i=0; i<str.length; i++) {
    ret += (str.charAt(i).charCodeAt(0) - charCodeOfA).toString(16);
  }
  return ret;
}

console.log(encrypt('111111', "k.www.10jqka.com", "offset.10jqkacom"))
